def f(inputs: List[Tuple[int, int, List[Tuple[int, int]], List[Tuple[int, int]]]]): 
    def build_graph(n, edges):
        graph = {i: [] for i in range(n + 1)}
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        return graph

    def dfs(u, graph, colors):
        for v in graph[u]:
            if colors[v] == -1:
                colors[v] = colors[u] ^ 1
                dfs(v, graph, colors)
            elif colors[v] == colors[u]:
                return False
        return True

    for C, W, edgelist, queries in inputs:
        if C == 0 and W == 0:
            break
        graph = build_graph(C + 1, edgelist)
        colors = [-1] * (C + 1)
        ans = []
        for s, t in queries:
            if colors[s] == -1:
                colors[s] = 0
                if not dfs(s, graph, colors):
                    ans.append(f"{s} cannot reach {t}")
                else:
                    ans.append(f"{s} can reach {t}")
            else:
                if colors[s] == colors[t]:
                    ans.append(f"{s} cannot reach {t}")
                else:
                    ans.append(f"{s} can reach {t}")
        print(*ans, sep="\n")
